import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.text.Normalizer;
import java.security.MessageDigest;
import java.util.*;
import java.util.stream.Stream;
import java.util.concurrent.ConcurrentHashMap;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

/**
 * SecureFileVault - Authenticated file storage with integrity verification.
 * Supports Unicode filenames with proper normalization for cross-platform compatibility.
 */
public class SecureFileVault {
    private static final String VAULT_ROOT = "/var/vault/data";
    private static final int MAX_FILENAME_LENGTH = 255;
    private static final int MAX_FILE_SIZE = 10 * 1024 * 1024;
    private final byte[] signingKey;
    private final ConcurrentHashMap<String, String> sessionTokens = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Integer> rateLimiter = new ConcurrentHashMap<>();
    private static final int RATE_LIMIT = 100;

    public SecureFileVault(byte[] key) {
        this.signingKey = Arrays.copyOf(key, key.length);
    }

    /**
     * Authenticates a session token using HMAC-SHA256.
     * Returns the username if valid, null otherwise.
     */
    public String authenticateToken(String token) {
        if (token == null || token.length() < 10) return null;
        String[] parts = token.split("\\.", 3);
        if (parts.length != 3) return null;

        String username = parts[0];
        String timestamp = parts[1];
        String providedSig = parts[2];

        // Check token expiry (1 hour)
        try {
            long ts = Long.parseLong(timestamp);
            if (System.currentTimeMillis() - ts > 3600000) return null;
        } catch (NumberFormatException e) {
            return null;
        }

        // Verify HMAC
        String expectedSig = computeHmac(username + "." + timestamp);
        if (expectedSig == null) return null;
        if (!MessageDigest.isEqual(
                expectedSig.getBytes(StandardCharsets.UTF_8),
                providedSig.getBytes(StandardCharsets.UTF_8))) {
            return null;
        }
        return username;
    }

    private String computeHmac(String data) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(signingKey, "HmacSHA256"));
            byte[] raw = mac.doFinal(data.getBytes(StandardCharsets.UTF_8));
            return Base64.getUrlEncoder().withoutPadding().encodeToString(raw);
        } catch (Exception e) {
            return null;
        }
    }

    /**
     * Validates that a username is safe for use as a directory name.
     * Defensive check: even though usernames come from HMAC-authenticated
     * tokens, they must not contain path-traversal characters.
     */
    private boolean isUsernameSafe(String username) {
        if (username == null || username.isEmpty()) return false;
        if (username.length() > MAX_FILENAME_LENGTH) return false;
        if (username.indexOf('\0') >= 0) return false;
        if (username.contains("..")) return false;
        if (username.contains("/")) return false;
        if (username.contains("\\")) return false;
        if (username.startsWith(".")) return false;
        return true;
    }

    /**
     * Validates that a filename is safe for filesystem operations.
     * Checks for path traversal sequences and null bytes.
     */
    private boolean isFilenameSafe(String filename) {
        if (filename == null || filename.isEmpty()) return false;
        if (filename.length() > MAX_FILENAME_LENGTH) return false;

        // Block null bytes
        if (filename.indexOf('\0') >= 0) return false;

        // Block path traversal - check for dangerous sequences
        if (filename.contains("..")) return false;
        if (filename.contains("/")) return false;
        if (filename.contains("\\")) return false;

        // Block hidden files
        if (filename.startsWith(".")) return false;

        return true;
    }

    /**
     * Normalizes a Unicode filename for cross-platform storage compatibility.
     * Uses NFC normalization to ensure consistent representation.
     * This handles cases like combining diacritics, fullwidth characters, etc.
     */
    private String normalizeFilename(String filename) {
        // NFC normalization for consistent Unicode representation
        String normalized = Normalizer.normalize(filename, Normalizer.Form.NFKC);
        // Trim any resulting whitespace
        normalized = normalized.trim();
        return normalized;
    }

    /**
     * Resolves the full path for a file within the vault.
     * Security: normalizes FIRST, then validates, then verifies path containment.
     */
    private Path resolveFilePath(String username, String filename) {
        // Defensive: validate username before using it in a path
        if (!isUsernameSafe(username)) {
            return null;
        }

        // Step 1: Normalize for cross-platform Unicode compatibility FIRST
        String normalizedName = normalizeFilename(filename);

        // Step 2: Validate the normalized filename for safety
        if (!isFilenameSafe(normalizedName)) {
            return null;
        }

        // Step 3: Construct the path within user's directory
        Path userDir = Paths.get(VAULT_ROOT, username).normalize();
        Path filePath = userDir.resolve(normalizedName).normalize();

        // Step 4: Final containment check - ensure resolved path is within user dir
        if (!filePath.startsWith(userDir)) {
            return null;
        }

        return filePath;
    }

    /**
     * Stores a file in the authenticated user's vault.
     */
    public boolean storeFile(String token, String filename, byte[] content) {
        String username = authenticateToken(token);
        if (username == null) return false;

        // Rate limiting
        int count = rateLimiter.merge(username, 1, Integer::sum);
        if (count > RATE_LIMIT) return false;

        if (content == null || content.length > MAX_FILE_SIZE) return false;

        Path filePath = resolveFilePath(username, filename);
        if (filePath == null) return false;

        try {
            Files.createDirectories(filePath.getParent());
            Files.write(filePath, content, 
                StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);
            return true;
        } catch (IOException e) {
            return false;
        }
    }

    /**
     * Retrieves a file from the authenticated user's vault.
     */
    public byte[] retrieveFile(String token, String filename) {
        String username = authenticateToken(token);
        if (username == null) return null;

        // Rate limiting
        int count = rateLimiter.merge(username, 1, Integer::sum);
        if (count > RATE_LIMIT) return null;

        Path filePath = resolveFilePath(username, filename);
        if (filePath == null) return null;

        try {
            if (!Files.exists(filePath)) return null;
            byte[] data = Files.readAllBytes(filePath);
            if (data.length > MAX_FILE_SIZE) return null;
            return data;
        } catch (IOException e) {
            return null;
        }
    }

    /**
     * Lists files in the authenticated user's vault.
     */
    public List<String> listFiles(String token) {
        String username = authenticateToken(token);
        if (username == null) return Collections.emptyList();
        if (!isUsernameSafe(username)) return Collections.emptyList();

        Path userDir = Paths.get(VAULT_ROOT, username).normalize();
        List<String> files = new ArrayList<>();

        try {
            if (!Files.isDirectory(userDir)) return files;
            // Use try-with-resources to close the directory stream
            try (Stream<Path> stream = Files.list(userDir)) {
                stream.forEach(p -> files.add(p.getFileName().toString()));
            }
        } catch (IOException e) {
            // Return what we have
        }
        return Collections.unmodifiableList(files);
    }

    /**
     * Deletes a file from the authenticated user's vault.
     */
    public boolean deleteFile(String token, String filename) {
        String username = authenticateToken(token);
        if (username == null) return false;

        Path filePath = resolveFilePath(username, filename);
        if (filePath == null) return false;

        try {
            return Files.deleteIfExists(filePath);
        } catch (IOException e) {
            return false;
        }
    }
}
